129	  async generateJson(
130	    options: GenerateJsonOptions,
131	  ): Promise<Record<string, unknown>> {
132	    const {
133	      schema,
134	      modelConfigKey,
135	      contents,
136	      systemInstruction,
137	      abortSignal,
138	      promptId,
139	      role,
140	      maxAttempts,
141	    } = options;
142	
143	    const { model } =
144	      this.config.modelConfigService.getResolvedConfig(modelConfigKey);
145	
146	    const shouldRetryOnContent = (response: GenerateContentResponse) => {
147	      const text = getResponseText(response)?.trim();
148	      if (!text) {
149	        return true; // Retry on empty response
150	      }
151	      try {
152	        // We don't use the result, just check if it's valid JSON
153	        JSON.parse(this.cleanJsonResponse(text, model));
154	        return false; // It's valid, don't retry
155	      } catch {
156	        return true; // It's not valid, retry
157	      }
158	    };
159	
160	    const result = await this._generateWithRetry(
161	      {
162	        modelConfigKey,
163	        contents,
164	        abortSignal,
165	        promptId,
166	        maxAttempts,
167	        systemInstruction,
168	        additionalProperties: {
169	          responseJsonSchema: schema,
170	          responseMimeType: 'application/json',
171	        },
172	      },
173	      shouldRetryOnContent,
174	      'generateJson',
175	      role,
176	    );
177	
178	    // If we are here, the content is valid (not empty and parsable).
179	    // eslint-disable-next-line @typescript-eslint/no-unsafe-return
180	    return JSON.parse(
181	      this.cleanJsonResponse(getResponseText(result)!.trim(), model),
182	    );
183	  }
