185	  async generateEmbedding(texts: string[]): Promise<number[][]> {
186	    if (!texts || texts.length === 0) {
187	      return [];
188	    }
189	    const embedModelParams: EmbedContentParameters = {
190	      model: this.config.getEmbeddingModel(),
191	      contents: texts,
192	    };
193	
194	    const embedContentResponse =
195	      await this.contentGenerator.embedContent(embedModelParams);
196	    if (
197	      !embedContentResponse.embeddings ||
198	      embedContentResponse.embeddings.length === 0
199	    ) {
200	      throw new Error('No embeddings found in API response.');
201	    }
202	
203	    if (embedContentResponse.embeddings.length !== texts.length) {
204	      throw new Error(
205	        `API returned a mismatched number of embeddings. Expected ${texts.length}, got ${embedContentResponse.embeddings.length}.`,
206	      );
207	    }
208	
209	    return embedContentResponse.embeddings.map((embedding, index) => {
210	      const values = embedding.values;
211	      if (!values || values.length === 0) {
212	        throw new Error(
213	          `API returned an empty embedding for input text at index ${index}: "${texts[index]}"`,
214	        );
215	      }
216	      return values;
217	    });
218	  }
