26	export const RollingSummaryProcessorOptionsSchema: JSONSchemaType<RollingSummaryProcessorOptions> =
27	  {
28	    type: 'object',
29	    properties: {
30	      target: {
31	        type: 'string',
32	        enum: ['incremental', 'freeNTokens', 'max'],
33	        nullable: true,
34	      },
35	      freeTokensTarget: { type: 'number', nullable: true },
36	      maxRollingSummaries: { type: 'number', nullable: true },
37	      systemInstruction: { type: 'string', nullable: true },
38	    },
39	    required: [],
40	  };
