42	export function createRollingSummaryProcessor(
43	  id: string,
44	  env: ContextEnvironment,
45	  options: RollingSummaryProcessorOptions,
46	): ContextProcessor {
47	  const generateRollingSummary = async (
48	    nodes: ConcreteNode[],
49	  ): Promise<string> => {
50	    let transcript = '';
51	    for (const node of nodes) {
52	      const payload = node.payload;
53	      let nodeContent = '';
54	      if (payload.text) {
55	        nodeContent = payload.text;
56	      } else if (payload.functionCall) {
57	        nodeContent = `CALL: ${payload.functionCall.name}(${JSON.stringify(payload.functionCall.args)})`;
58	      } else if (payload.functionResponse) {
59	        nodeContent = `RESPONSE: ${JSON.stringify(payload.functionResponse.response)}`;
60	      }
61	      transcript += `[${node.type}]: ${nodeContent}\n`;
62	    }
63	
64	    const systemPrompt =
65	      options.systemInstruction ??
66	      `You are an expert context compressor. Your job is to drastically shorten the provided conversational transcript while preserving the absolute core semantic meaning, facts, and intent. Omit all conversational filler, pleasantries, or redundant information. Return ONLY the compressed summary.`;
67	
68	    const response = await env.llmClient.generateContent({
69	      role: LlmRole.UTILITY_COMPRESSOR,
70	      modelConfigKey: { model: 'gemini-3-flash-base' },
71	      promptId: env.promptId,
72	      abortSignal: new AbortController().signal,
73	      contents: [{ role: 'user', parts: [{ text: transcript }] }],
74	      systemInstruction: { role: 'system', parts: [{ text: systemPrompt }] },
75	    });
76	
77	    const candidate = response.candidates?.[0];
78	    const textPart = candidate?.content?.parts?.[0];
79	    return textPart?.text || '';
80	  };
81	
82	  return {
83	    id,
84	    name: 'RollingSummaryProcessor',
85	    process: async ({ targets }: ProcessArgs) => {
86	      if (targets.length === 0) return targets;
87	
88	      const strategy = options.target ?? 'max';
89	      const nodesToSummarize: ConcreteNode[] = [];
90	
91	      if (strategy === 'incremental') {
92	        // 'incremental' simply summarizes the minimum viable chunk (the oldest 2 nodes), ignoring token math.
93	        for (const node of targets) {
94	          if (node.id === targets[0].id && node.type === 'USER_PROMPT') {
95	            continue; // Keep system prompt
96	          }
97	          nodesToSummarize.push(node);
98	          if (nodesToSummarize.length >= 2) break; // We have enough for a minimum rolling summary
99	        }
100	      } else {
101	        let targetTokensToRemove = 0;
102	        if (strategy === 'freeNTokens') {
103	          targetTokensToRemove = options.freeTokensTarget ?? Infinity;
104	        } else if (strategy === 'max') {
105	          targetTokensToRemove = Infinity;
106	        }
107	
108	        if (targetTokensToRemove > 0) {
109	          let deficitAccumulator = 0;
110	          for (const node of targets) {
111	            if (node.id === targets[0].id && node.type === 'USER_PROMPT') {
112	              continue; // Keep system prompt
113	            }
114	            nodesToSummarize.push(node);
115	            deficitAccumulator += env.tokenCalculator.getTokenCost(node);
116	            if (deficitAccumulator >= targetTokensToRemove) break;
117	          }
118	        }
119	      }
120	
121	      if (nodesToSummarize.length < 2) return targets; // Not enough context to summarize
122	
123	      try {
124	        // Synthesize the rolling summary synchronously
125	        const snapshotText = await generateRollingSummary(nodesToSummarize);
126	        const newId = randomUUID();
127	
128	        const summaryNode: RollingSummary = {
129	          id: newId,
130	          turnId: newId,
131	          type: NodeType.ROLLING_SUMMARY,
132	          timestamp: nodesToSummarize[nodesToSummarize.length - 1].timestamp,
133	          role: 'user',
134	          payload: { text: snapshotText },
135	          abstractsIds: nodesToSummarize.map((n) => n.id),
136	        };
137	
138	        const consumedIds = nodesToSummarize.map((n) => n.id);
139	        const returnedNodes = targets.filter(
140	          (t) => !consumedIds.includes(t.id),
141	        );
142	        const firstRemovedIdx = targets.findIndex((t) =>
143	          consumedIds.includes(t.id),
144	        );
145	
146	        if (firstRemovedIdx !== -1) {
147	          const idx = Math.max(0, firstRemovedIdx);
148	          returnedNodes.splice(idx, 0, summaryNode);
149	        } else {
150	          returnedNodes.unshift(summaryNode);
151	        }
152	
153	        return returnedNodes;
154	      } catch (e) {
155	        debugLogger.error('RollingSummaryProcessor failed sync backstop', e);
156	        return targets;
157	      }
158	    },
159	  };
160	}
