import type { ConcreteNode } from '../graph/types.js';

/**
 * Options controlling how a node transcript is rendered for an LLM.
 */
export interface FormatNodesOptions {
  /**
   * The maximum number of characters allowed for a single tool (function)
   * response before it is truncated. Defaults to 2000.
   */
  maxToolResponseChars?: number;
}

const DEFAULT_MAX_TOOL_RESPONSE_CHARS = 2000;

/**
 * Truncates the middle of an over-long string, keeping a head and tail slice
 * and replacing the excised middle with a marker describing how many
 * characters were removed.
 *
 * Produces: `prefix... [TRUNCATED N chars] ...suffix`
 */
function truncateMiddle(text: string, maxChars: number): string {
  if (text.length <= maxChars) {
    return text;
  }

  const headLen = Math.ceil(maxChars / 2);
  const tailLen = Math.floor(maxChars / 2);
  const prefix = text.slice(0, headLen);
  const suffix = text.slice(text.length - tailLen);
  const removed = text.length - prefix.length - suffix.length;

  return `${prefix}... [TRUNCATED ${removed} chars] ...${suffix}`;
}

/**
 * Renders a list of ConcreteNodes into a compact, deterministic transcript
 * suitable for feeding to a utility LLM.
 *
 * Each line has the shape: `[Turn N] [ROLE] [TYPE]: content`
 *
 * - Text payloads use the raw node text.
 * - Function calls render as `CALL: name({args})`.
 * - Function responses render as `[SEMANTIC_WRAPPER (toolName)]: {json_response}`
 *   and are truncated in the middle when they exceed `maxToolResponseChars`.
 *
 * Turn numbers are assigned sequentially (1-based) as new `turnId`s are
 * encountered. Nodes without a role default to `SYSTEM`.
 */
export function formatNodesForLlm(
  nodes: readonly ConcreteNode[],
  options: FormatNodesOptions = {},
): string {
  const maxToolResponseChars =
    options.maxToolResponseChars ?? DEFAULT_MAX_TOOL_RESPONSE_CHARS;

  const turnNumbers = new Map<string, number>();
  let nextTurnNumber = 1;

  let transcript = '';
  for (const node of nodes) {
    let turnNumber = turnNumbers.get(node.turnId);
    if (turnNumber === undefined) {
      turnNumber = nextTurnNumber++;
      turnNumbers.set(node.turnId, turnNumber);
    }

    const role = (node.role ?? 'SYSTEM').toString().toUpperCase();

    const payload = node.payload;
    let content = '';
    if (payload.text) {
      content = payload.text;
    } else if (payload.functionCall) {
      content = `CALL: ${payload.functionCall.name}(${JSON.stringify(
        payload.functionCall.args,
      )})`;
    } else if (payload.functionResponse) {
      const toolName = payload.functionResponse.name;
      const jsonResponse = truncateMiddle(
        JSON.stringify(payload.functionResponse.response),
        maxToolResponseChars,
      );
      content = `[SEMANTIC_WRAPPER (${toolName})]: ${jsonResponse}`;
    }

    transcript += `[Turn ${turnNumber}] [${role}] [${node.type}]: ${content}\n`;
  }

  return transcript;
}
