export interface SnapshotState {
  /** Outstanding work the agent is expected to complete. */
  active_tasks: string[];
  /** Durable facts discovered about the project, code, or environment. */
  discovered_facts: string[];
  /** Hard constraints and stated user preferences that must be honored. */
  constraints_and_preferences: string[];
  /** A short rolling summary of the most recent conversational events. */
  recent_arc: string[];
}

/**
 * The incremental patch the LLM emits. New items are appended to the master
 * state; `deletions` remove existing items (e.g. a completed task) by exact
 * text match.
 */
interface SnapshotPatch {
  active_tasks?: string[];
  discovered_facts?: string[];
  constraints_and_preferences?: string[];
  recent_arc?: string[];
  deletions?: string[];
}

/** Information about a baseline snapshot located within a node list. */
export interface BaselineSnapshotInfo {
  /** The snapshot node itself. */
  node: ConcreteNode;
  /** The index of the snapshot node within the scanned list. */
  index: number;
  /** The (non-empty) text payload of the snapshot. */
  text: string;
}

const DEFAULT_MAX_SUMMARY_TURNS = 5;
const DEFAULT_MAX_STATE_TOKENS = 4000;

/** The ordered list of state fields for structural iteration. */
const STATE_FIELDS: Array<keyof SnapshotState> = [
  'active_tasks',
  'discovered_facts',
  'constraints_and_preferences',
  'recent_arc',
];

/**
 * The order in which items are dropped when enforcing the token budget.
 * Lowest priority (dropped first) to highest priority (dropped last):
 * the ephemeral recent arc goes first, hard constraints are preserved longest.
 */
const DROP_PRIORITY: Array<keyof SnapshotState> = [
  'recent_arc',
  'discovered_facts',
  'active_tasks',
  'constraints_and_preferences',
];

