  type: 'object',
  properties: {
    active_tasks: { type: 'array', items: { type: 'string' } },
    discovered_facts: { type: 'array', items: { type: 'string' } },
    constraints_and_preferences: { type: 'array', items: { type: 'string' } },
    recent_arc: { type: 'array', items: { type: 'string' } },
    deletions: { type: 'array', items: { type: 'string' } },
  },
};

function createEmptyState(): SnapshotState {
  return {
    active_tasks: [],
    discovered_facts: [],
    constraints_and_preferences: [],
    recent_arc: [],
  };
}

/**
 * Coerces an arbitrary parsed object into a well-formed SnapshotState,
 * discarding any fields that are not string arrays.
 */
function normalizeState(raw: unknown): SnapshotState {
  const state = createEmptyState();
  if (!raw || typeof raw !== 'object') {
    return state;
  }
  const obj = raw as Record<string, unknown>;
  for (const field of STATE_FIELDS) {
    const value = obj[field];
    if (Array.isArray(value)) {
      state[field] = value.filter((v): v is string => typeof v === 'string');
    }
  }
  return state;
}

